// Cache existing provider_ids from Lead Pool into workflow static data.
// Runs once at start of run, so Dedup can read without hitting Sheets on every iteration.

const staticData = $getWorkflowStaticData('global');

staticData.existingIds = $input.all()
  .map(x => x.json && x.json.provider_id)
  .filter(Boolean);

staticData.seenThisRun = [];

return $input.all().length > 0
  ? $input.all()
  : [{ json: { cacheInitialized: true, cachedCount: staticData.existingIds.length } }];

const slices = $('ICP Query Builder').all();
const cursorRows = $('Read Cursors').all();

const cursorMap = {};
for (const row of cursorRows) {
  const j = row.json || {};
  if (j.slice) {
    cursorMap[j.slice] = {
      last_start: Number(j.last_start) || 0,
      total_available: j.total_available !== '' && j.total_available != null
        ? Number(j.total_available)
        : null
    };
  }
}

return slices.map(s => {
  const sliceName = s.json.slice;
  const cur = cursorMap[sliceName] || { last_start: 0, total_available: null };

  let start = cur.last_start;
  if (cur.total_available !== null && start >= cur.total_available) {
    start = 0;
  }

  return {
    json: {
      slice: s.json.slice,
      keywords: s.json.keywords,
      limit: s.json.limit,
      start: start,
      prev_total: cur.total_available
    }
  };
});

const slice = $('Merge Cursors into Slices').item.json.slice;
const payload = $input.first().json;
const body = Array.isArray(payload) ? payload[0] : payload;
const raw = body && (body.items || body.results) || [];

return raw.map(r => {
  const first = r.first_name || '';
  const last = r.last_name || '';
  const composedName = `${first} ${last}`.trim();

  return {
    json: {
      provider_id: r.id || r.provider_id || r.public_identifier || null,
      public_identifier: r.public_identifier || null,
      name: r.name || composedName || null,
      headline: r.headline || '',
      network_distance: r.network_distance || r.distance || null,
      location: r.location || r.location_name || '',
      slice: slice,
      discovered_at: new Date().toISOString()
    }
  };
}).filter(x => 
  x.json.provider_id && 
  x.json.name && 
  x.json.name !== 'LinkedIn Member' &&
  x.json.public_identifier
);

const sliceKeywords = {
  nonprofit_ed:        ['executive director', 'nonprofit', 'non-profit', 'nfp', '501c3', '501(c)(3)', 'charity', 'ngo'],
  nonprofit_dev:       ['development director', 'director of development', 'fundraising', 'advancement', 'philanthropy'],
  nonprofit_grants:    ['grant writer', 'grants writer', 'grant', 'grants'],
  nonprofit_prog:      ['program director', 'director of programs', 'program manager'],
  smb_founder_climate: ['founder', 'co-founder', 'cofounder', 'ceo', 'chief exec'],
  smb_founder_agri:    ['founder', 'co-founder', 'cofounder', 'ceo', 'chief exec'],
  smb_founder_edu:     ['founder', 'co-founder', 'cofounder', 'ceo', 'chief exec'],
  smb_founder_biotech: ['founder', 'co-founder', 'cofounder', 'ceo', 'chief exec'],
  church_pastor:       ['pastor', 'minister', 'church', 'ministry'],
  church_admin:        ['administrator', 'admin', 'church', 'ministry', 'operations'],
  muni_commdev:        ['community development', 'city', 'municipal', 'council', 'planning'],
  muni_grants:         ['grants manager', 'grants', 'city', 'municipal', 'council'],
  nonprofit_cdo:       ['chief development', 'cdo', 'philanthropy', 'fundraising'],
  nonprofit_founder:   ['founder', 'co-founder', 'cofounder', 'ceo'],
  nonprofit_president: ['president', 'ceo', 'chief exec'],
  foundation_prog:     ['program officer', 'foundation', 'philanthropy'],
  grants_coord:        ['grants coordinator', 'grants', 'grant'],
  grants_admin:        ['grants administrator', 'grants admin', 'grants'],
  smb_founder_food:    ['founder', 'co-founder', 'cofounder', 'ceo'],
  smb_founder_health:  ['founder', 'co-founder', 'cofounder', 'ceo'],
  church_missions:     ['missions', 'church', 'ministry'],
  church_ceo:          ['minister', 'pastor', 'ceo', 'executive'],
  muni_economic:       ['economic development', 'city', 'municipal', 'council'],
  edu_advancement:     ['advancement', 'university', 'college', 'institutional']
};

return $input.all().filter(item => {
  const headline = (item.json.headline || '').toLowerCase();
  const keywords = sliceKeywords[item.json.slice] || [];
  if (keywords.length === 0) return true;
  return keywords.some(kw => headline.includes(kw));
});

// US + EU Location Gate
const US_STATES = /\b(AL|AK|AZ|AR|CA|CO|CT|DE|FL|GA|HI|ID|IL|IN|IA|KS|KY|LA|ME|MD|MA|MI|MN|MS|MO|MT|NE|NV|NH|NJ|NM|NY|NC|ND|OH|OK|OR|PA|RI|SC|SD|TN|TX|UT|VT|VA|WA|WV|WI|WY|DC)\b/;
const US_MARKERS = /\b(united states|usa|u\.s\.|u\.s\.a\.|greater .* area|.*metropolitan area)\b/i;
const EU_MARKERS = /\b(united kingdom|england|scotland|wales|northern ireland|ireland|london|manchester|birmingham|leeds|edinburgh|glasgow|bristol|dublin|germany|berlin|munich|hamburg|frankfurt|cologne|stuttgart|france|paris|lyon|marseille|toulouse|nice|spain|madrid|barcelona|valencia|seville|netherlands|amsterdam|rotterdam|hague|utrecht|eindhoven|belgium|brussels|antwerp|ghent|italy|rome|milan|naples|turin|florence|switzerland|zurich|geneva|basel|bern|austria|vienna|salzburg|denmark|copenhagen|aarhus|sweden|stockholm|gothenburg|malmö|norway|oslo|bergen|finland|helsinki|espoo|portugal|lisbon|porto|poland|warsaw|krakow|czech|prague|greece|athens|hungary|budapest|romania|bucharest|luxembourg|malta|estonia|latvia|lithuania|slovakia|slovenia|croatia|bulgaria|cyprus|iceland|liechtenstein|europe|european union|eu)\b/i;

return $input.all().filter(item => {
  const loc = (item.json.location || '').trim();
  if (!loc) return false;
  return US_STATES.test(loc) || US_MARKERS.test(loc) || EU_MARKERS.test(loc);
});

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.existingIds))  staticData.existingIds  = [];
if (!Array.isArray(staticData.seenThisRun))  staticData.seenThisRun  = [];

const existingIds = new Set([
  ...staticData.existingIds,
  ...staticData.seenThisRun
]);

const candidates = $('US + EU Location Gate').all();
const newLeads = candidates.filter(
  item => item.json.provider_id && !existingIds.has(item.json.provider_id)
);

staticData.seenThisRun.push(...newLeads.map(x => x.json.provider_id));

return newLeads.map(item => ({
  json: { ...item.json, status: 'New' }
}));

